parameters.query:
MATCH (a:UndergroundStation)-[r:LINK]->(b:UndergroundStation)
WHERE NOT EXISTS {
  MATCH p = (a)-[:LINK*]-(b)
  WHERE none(rel IN relationships(p) WHERE id(rel) = id(r))
}
RETURN count(r) AS bridgeRelationshipCount

