parameters.query:
MATCH (start:UndergroundStation {name:'Canary Wharf'})
MATCH (target:UndergroundStation)
WHERE NOT EXISTS {
  MATCH p = shortestPath((start)-[:LINK*]->(target))
}
RETURN count(target) AS unreachableCount, collect(target.name) AS unreachableStops

MATCH (start:UndergroundStation {name:'Canary Wharf'})
MATCH (target:UndergroundStation)
WHERE target <> start AND NOT EXISTS {
  MATCH p = shortestPath((start)-[:LINK*]->(target))
}
RETURN count(target) AS unreachableCount, collect(target.name) AS unreachableStops

