parameters.query:
MATCH (root:UndergroundStation {name:$rootName})
CALL {
  WITH root
  MATCH (n:UndergroundStation)
  WHERE NOT EXISTS { MATCH (root)-[:LINK*0..]->(n) }
  RETURN count(n) AS notReachableFromRoot
}
CALL {
  WITH root
  MATCH (n:UndergroundStation)
  WHERE NOT EXISTS { MATCH (n)-[:LINK*0..]->(root) }
  RETURN count(n) AS cannotReachRoot
}
RETURN notReachableFromRoot, cannotReachRoot

